INSERT INTO match_videos VALUES(1,'-9Pz1RwmEUE','en',NULL,NULL,NULL,'AFTV(아스날 팬)','경기 후 반응','2026-08-31',0,'https://www.youtube.com/watch?v=-9Pz1RwmEUE','reports/transcripts/-9Pz1RwmEUE.en.md','감독회견',NULL,NULL,NULL,'전사 헤더 파싱 + observations 역인용 산출 (scripts/index_transcripts.py, 2026-09-15)','MEDIUM-HIGH(메타) — 채널·제목·게시일은 전사 헤더 파싱값이다. ⚠️ 전사 본문은 **유튜브 자동 생성 자막**이라 오인식이 있다(docs/30 대조표) — 인용 시 auto-caption 명기·원문+번역 병기(불변규칙 11). 경기 귀속은 상대팀 표기+날짜 창으로 단일 특정된 건만 붙였다.');
INSERT INTO match_videos VALUES(2,'0PquXppQweg','en',NULL,1,'AVL','UTV | Aston Villa Fan Channel','HOW ALEJANDRO GARNACHO FITS INTO THE UNAI EMERY SYSTEM WITH @BlueBrotherCFC','2026-07-23',0,'https://www.youtube.com/watch?v=0PquXppQweg','reports/transcripts/0PquXppQweg.en.md','선수스카우팅','UTV × 첼시 팬(Charlie)의 가르나초 대담 — ⭐⭐ **외부(전 소속 팬) 관점의 솔직한 평가**가 이 영상의 가치다. 결론은 **「축구선수로서 매우 제한적이지만, 할 수 있는 그 제한된 것들은 실제로 매우 잘한다 — 그래서 프로파일링이 전부다」**이고, ⭐ **태도 문제는 첼시에서 없었다**고 명시적으로 부인했다.',unistr('⭐⭐ **핵심 평가** — 「for me **he''s very limited as a footballer, but the limited things that he can do he''s actually very good at them. So it''s about **profiling him in the right way** to get the most out of his limited skill set」 = 「선수로서 매우 제한적이지만 **할 수 있는 그 제한된 것들은 정말 잘한다**. 그래서 **올바르게 프로파일링해 최대치를 끌어내는 것**이 문제다」.\u000a⭐⭐ **태도 문제 부인** — 「there were **no attitude issues or off-field issues** or anything like that… from an attitude point of view, there were no issues at Chelsea. It was **just a pure ability situation**」 = 「태도 문제나 경기장 밖 문제는 **없었다**… 순전히 **기량 문제**였다」. 다만 「맨유 시절에는 그런 의혹들이 있었다 · **복귀 트래킹은 그의 것이 아니었고 백포스트에서 자기 상대를 놓치는 게잦았다**」고 구분해 진술.\u000a⭐ 수치 맥락 — 「사실상 지난 시즌 좌측 1선택이었는데 **리그 득점은 1골** · 대부분의 골이 리그컵에서 나왔다」. 첼시 팬베이스는 「영입 시점부터 **거의 만장일치로 반대**했고 실제로 그렇게 전개됐다」.\u000a⭐⭐ **필요 조건을 환경으로 특정** — 「he''s probably been a bit **badly advised. His confidence is low**… he needs to go somewhere where **he''s going to be loved, where there''s going to be an arm round the shoulder from the manager** to boost his confidence and make him feel wanted」 ⇒ **감독의 정서적 관리**가 회복 조건이라는 진단.\u000a⭐ 진행자의 프레이밍 — 「에메리는 **이런 프로젝트 선수를 사랑한다** — 래시포드·산초에 이어 가르나초까지 봤다 · 그 기운에서 그가 잠금을 풀려 한다」. ⇒ **AVL의 반복 패턴**(회복형 윙어 영입)으로 위치시켰다.\u000a⚠️ 양쪽 팬베이스가 모두 반대했던 영입이라는 점을 두 진행자가 함께 확인했다 — 「그는 그 짐(baggage)을 안고 온다」.'),'479','전사 헤더 파싱 + observations 역인용 산출 (scripts/index_transcripts.py, 2026-09-15)','MEDIUM-HIGH(메타) — 채널·제목·게시일은 전사 헤더 파싱값이다. ⚠️ 전사 본문은 **유튜브 자동 생성 자막**이라 오인식이 있다(docs/30 대조표) — 인용 시 auto-caption 명기·원문+번역 병기(불변규칙 11). 경기 귀속은 상대팀 표기+날짜 창으로 단일 특정된 건만 붙였다. · [요약 2026-09-15] summary/key_points는 **전사 원문을 읽고 쓴 것**이다(영상 미시청). ⚠️ auto-caption 오인식 가능 — 인물명·수치는 실측과 교차검증 필요(docs/30 대조표). 인용은 원문+한국어 번역 병기(불변규칙 11).');
INSERT INTO match_videos VALUES(3,'0bPmh_Ef4L4','en',30,1,'AVL','1874 : The Aston Villa Channel','Back at Villa Park as Villa Fall to Narrow Arsenal Defeat','2026-09-01',1,'https://www.youtube.com/watch?v=0bPmh_Ef4L4','reports/transcripts/0bPmh_Ef4L4.en.md','경기반응','1874의 「Through the Turnstiles」 — 경기장 동행 브이로그(진행자·아버지·Martin). ⭐ **전술 분석물이 아니다**. 아버지의 건강·이동 문제와 노스 스탠드 철거에 따른 좌석 이동이 내용의 큰 부분이고, 전술 가치는 **이적 창 정서와 예상 XI 정도**다. ⇒ 우리 축에서는 **팬 정서·구장 맥락 자료**로만 쓴다.',unistr('⚠️ **장르 주의 — 이 영상은 경기 분석이 아니다.** 진행자가 「아버지의 이동성·건강이 나빠져 빌라 파크에서의 시간을 기록해 두려고」 시작한 시리즈이고, 대화의 상당 부분이 보행 보조기·좌석·음식 이야기다. 전술 인용원으로 쓰기에 부적합하다.\u000a⭐ 스쿼드 정서 — 「여섯 명쯤 나갔다… **완전한 재건이라는 게 보인다**. 이번 시즌 무슨 일이 일어날지 모르지만 에메리를 신뢰한다」. 가장 아쉬운 이탈로 **왓킨스와 로저스**를 들고, 「틸레만스의 맨유행은 정말 빨리 진행돼 놀랐다」고 언급.\u000a⭐ **하우드-벨리스에 대한 유보** — 「I''m not 100% sure on that as a **replacement**. But I''m happy when I''m wrong」 = 「대체자로서 100% 확신하지 못한다. 틀리면 기쁘겠다」 ⇒ 콘사 대체 판정에 **채널 스스로 의문**을 남겼다(우리 obs 축의 「완비사카형 앵커로 취급 불가」 판정과 같은 방향의 불확실성).\u000a구장 맥락 — **노스 스탠드 철거 공사**로 좌석이 이동했고, 진행자는 「분위기에 큰 영향은 없었고 관중이 훌륭했다」고 평가. ⇒ 홈 경기 분위기 축 참고.\u000a예상 XI — 「지난주와 같은 팀에 **스즈키와 잭슨 투입**」. 스코어 예상은 「0-0 아니면 대패」라는 농담.'),NULL,'전사 헤더 파싱 + observations 역인용 산출 (scripts/index_transcripts.py, 2026-09-15)','MEDIUM-HIGH(메타) — 채널·제목·게시일은 전사 헤더 파싱값이다. ⚠️ 전사 본문은 **유튜브 자동 생성 자막**이라 오인식이 있다(docs/30 대조표) — 인용 시 auto-caption 명기·원문+번역 병기(불변규칙 11). 경기 귀속은 상대팀 표기+날짜 창으로 단일 특정된 건만 붙였다. · [요약 2026-09-15] summary/key_points는 **전사 원문을 읽고 쓴 것**이다(영상 미시청). ⚠️ auto-caption 오인식 가능 — 인물명·수치는 실측과 교차검증 필요(docs/30 대조표). 인용은 원문+한국어 번역 병기(불변규칙 11).');
INSERT INTO match_videos VALUES(4,'1ZsBdIo-anI','en',NULL,NULL,NULL,'Bains Analysis','Xabi Alonso Has Completely Changed Chelsea','2026-08-24',0,'https://www.youtube.com/watch?v=1ZsBdIo-anI','reports/transcripts/1ZsBdIo-anI.en.md',NULL,NULL,NULL,NULL,'전사 헤더 파싱 + observations 역인용 산출 (scripts/index_transcripts.py, 2026-09-15)','MEDIUM-HIGH(메타) — 채널·제목·게시일은 전사 헤더 파싱값이다. ⚠️ 전사 본문은 **유튜브 자동 생성 자막**이라 오인식이 있다(docs/30 대조표) — 인용 시 auto-caption 명기·원문+번역 병기(불변규칙 11). 경기 귀속은 상대팀 표기+날짜 창으로 단일 특정된 건만 붙였다.');
INSERT INTO match_videos VALUES(5,'2DkYlBGnI1c','en',31,1,'AVL','The Villans','WHY DOESN''T EMERY PLAY HIS NEW SIGNINGS, OBSESSED WITH THE SYSTEM & THE JACKSON/WATKINS DIFFERENCE','2026-09-06',0,'https://www.youtube.com/watch?v=2DkYlBGnI1c','reports/transcripts/2DkYlBGnI1c.en.md','선수스카우팅','The Villans 헐전(0-0) 패널 리액션. ⭐ 핵심은 두 가지다 — ⑴ 이 경기는 「**매우 전형적인 에메리 원정**」이고 통제는 됐는데 결정력만 없었다는 평가 ⑵ **왓킨스→잭슨 전환에 팀이 적응하지 못하고 있다**는 진단. 밍스 선발 이유를 「권위(authority)」로 설명한 대목이 우리 cb_stopper 성향 판정과 맞물린다.',unistr('경기 성격 — 원문 「This is a very typical Aston Villa performance away from home... It''s all about control」 = 「매우 전형적인 빌라 원정 경기다. 전부 통제에 관한 것이다」. 잭슨·맥긴이 결정적 기회를 넣었다면 「완전히 다른 대화」였다는 것이 패널 공통 인식.\u000a⭐⭐ **왓킨스→잭슨 전환 적응 문제** — 원문 「Watkins does things that Jackson doesn''t do, and Jackson does things that Watkins doesn''t do」. 맥긴·부엔디아가 특히 잭슨과 맞추는 데 어려움을 겪고 있고 「시간이 필요하다」는 진단.\u000a⭐ **밍스 선발 이유 = 「권위」** — 원문 「Emry turned to Mings because he brought authority to the back」. 지난 시즌 카마라·틸레만스·맥긴 부상기에도 같은 선택을 했다는 전례 제시. ⇒ 빌드업형이 아니라 **수비 안정 축으로 쓰는 자원**이라는 외부 독립 증언.\u000a최우수 = 린델뢰프 — 「리더십·침착·통제」. 다만 마지막 5분엔 팀 전체가 통제를 잃어 질 수도 있었다고 인정.\u000a신입 미기용 해석 — 「감독이 아직 신입 다수를 신뢰하지 않는다」(음바예 미투입이 근거). 완전한 신뢰까지 「3주는 더」 걸릴 수 있다는 전망.\u000a심리 관찰 — 맥긴이 「등에 20kg을 짊어진 것처럼」 보이고 부엔디아도 프리시즌의 자유로움을 잃었다는 지적(경기력 저하를 상황 압박으로 해석).'),'473,475','전사 헤더 파싱 + observations 역인용 산출 (scripts/index_transcripts.py, 2026-09-15)','MEDIUM-HIGH(메타) — 채널·제목·게시일은 전사 헤더 파싱값이다. ⚠️ 전사 본문은 **유튜브 자동 생성 자막**이라 오인식이 있다(docs/30 대조표) — 인용 시 auto-caption 명기·원문+번역 병기(불변규칙 11). 경기 귀속은 상대팀 표기+날짜 창으로 단일 특정된 건만 붙였다.');
INSERT INTO match_videos VALUES(6,'2POgqu_eyzM','en',NULL,NULL,NULL,'Bains Analysis','Why Nicolas Jackson Is PERFECT for Aston Villa','2026-08-27',0,'https://www.youtube.com/watch?v=2POgqu_eyzM','reports/transcripts/2POgqu_eyzM.en.md','선수스카우팅','Bains Analysis의 잭슨 영입 스카우팅(데이터 기반). ⭐⭐ 핵심 주장은 **「잭슨은 팀을 더 좋게 만드는 선수」**이고, 왓킨스 대비 **24/25 시즌 기준 어시스트·슛·xG·슛어시스트·크로스·박스 터치·전진 런에서 모두 앞선다**(골만 왓킨스 우위)는 대조표다. ⭐ 마무리 문제는 **직접 슛 120개를 다 봐도 패턴이 없어 심리적 요인으로 추정**한다고 밝혔다.',unistr('⭐⭐ **「팀을 더 좋게 만드는 선수」** — 「anyone that watched his time at Chelsea would know he was almost like **the glue** at times within Chelsea''s attacking lineup… **his one-touch layoffs to his teammates was such an impressive trait**」 = 「첼시 시절을 본 사람은 그가 공격 라인의 **접착제**였다는 걸 안다… **원터치 레이오프가 인상적인 형질**이었다」.\u000a⭐⭐ **왓킨스 대비 수치(24/25 vs 왓킨스 마지막 시즌)** — 어시스트·슛·xG·슛어시스트·크로스·**박스 내 터치**·전진 런·파울 획득에서 **전부 잭슨 우위**, **골만 왓킨스 우위**. ⇒ 「생산의 종류가 다르다」는 구조적 대비.\u000a⭐ **유사점과 차이점을 나눠 제시** — 유사: 「왓킨스도 매우 적극적인 채널 러너였고 백라인을 늘렸다 · 잭슨도 정확히 같은 걸 한다」(위협 행동 발생 구역 그래픽 근거). 차이: **「잭슨이 중앙 지역, 특히 더 내려오는 상황에서 왓킨스보다 훨씬 편하다」** — 뉴캐슬전 예시로 「받고 돌아서 몰고 30~40야드 전진 후 패스」를 들었다.\u000a⭐ 볼 캐리 수치 — 「24/25 캐리 수치가 상위 백분위 · **슛으로 끝나는 캐리가 90분당 1회 이상**」 ⇒ 「받아서 몰고, 분리까지 만들어 슛을 낸다」.\u000a⭐⭐ **마무리 문제 진단 — 패턴이 없다** — 「I watched his last **120 shots** on Wyscout. I tried seeing is there a constant finish that he likes… he''s just **unpredictable**… I think this is probably more **psychological** than anything cuz he''s actually not a bad ball striker」 = 「최근 슛 120개를 Wyscout으로 봤다. 선호하는 일정한 마무리가 있는지 찾아봤는데… **예측 불가**다… 나쁜 슈터가 아니니 아마 **심리적** 요인일 것」. 첼시 2시즌 모두 xG 미달이었고 **바이에른에서 3년 만에 처음 xG 초과**했다는 점을 개선 신호로 제시.\u000a결론 — 「최상급 영입 · **왓킨스보다 낫다는 논쟁이 가능하고 실제로 그렇게 생각한다**」.'),NULL,'전사 헤더 파싱 + observations 역인용 산출 (scripts/index_transcripts.py, 2026-09-15)','MEDIUM-HIGH(메타) — 채널·제목·게시일은 전사 헤더 파싱값이다. ⚠️ 전사 본문은 **유튜브 자동 생성 자막**이라 오인식이 있다(docs/30 대조표) — 인용 시 auto-caption 명기·원문+번역 병기(불변규칙 11). 경기 귀속은 상대팀 표기+날짜 창으로 단일 특정된 건만 붙였다. · [요약 2026-09-15] summary/key_points는 **전사 원문을 읽고 쓴 것**이다(영상 미시청). ⚠️ auto-caption 오인식 가능 — 인물명·수치는 실측과 교차검증 필요(docs/30 대조표). 인용은 원문+한국어 번역 병기(불변규칙 11).');
INSERT INTO match_videos VALUES(7,'2gH4HvtkOls','en',NULL,1,'AVL','UTV | Aston Villa Fan Channel','THIS IS WHY EMERY PICKED GARNACHO OVER MBAYE','2026-07-28',0,'https://www.youtube.com/watch?v=2gH4HvtkOls','reports/transcripts/2gH4HvtkOls.en.md','프리시즌','UTV 이적 허브 — 음바예 영입을 앞두고 **채널 진행자가 「나쁜 기운이 든다」며 회의론을 제기한 회차**다. ⚠️ 내용의 상당 부분이 **제3자 매체(Touchline)가 보도한 대리인·엔투라지 관련 주장의 전달**이고, **우리 쪽에서 교차검증되지 않은 인물 관련 주장**이다 — 요약에서는 보도 존재 사실과 성격만 기록하고 **개인 신상 관련 세부는 옮기지 않는다**.',unistr('⭐ **채널의 입장 전환** — 「everybody has had (음바예) on their lips of a player that they want Villa to sign. **And the more I hear, the more I see, the more I read, the more I''m getting a bit of a bad vibe from this player**」 = 「모두가 영입을 원했지만 **들을수록·볼수록·읽을수록 나쁜 기운이 든다**」. 대안으로 다른 윙어 쪽으로 관심을 돌려야 한다는 의견을 냈다.\u000a⚠️ **근거는 제3자 보도** — 「같은 기자(에메리 아스날 시절 책을 쓴 사람)가 관련 기사를 흘리기 시작했다」며 **Touchline의 기사**를 낭독했다. 골자는 **선수 엔투라지가 대리인 후보들에게 과도한 요구를 했다는 주장**과 **PSG 내부의 규율 관련 우려, 1년 내 대리인 3회 교체, 커미션·초상권 배분 요구** 등이다.\u000a⛔ **이 행은 「그런 보도가 존재했다」까지만 기록한다** — ⑴ 우리 쪽 교차검증이 없고 ⑵ 미성년에 가까운 선수(당시 18세)와 그 가족에 관한 **신상·사생활 주장**이며 ⑶ 단일 매체 단독 보도다. 개인 신상 세부(식단·규율·종교 관련 언급 등)는 **의도적으로 옮기지 않았다**. 인사·전술 판단의 근거로 쓰지 않는다.\u000a⭐ **정황 관찰(검증 가능한 축)** — 진행자가 「공항에서 음바예와 부모가 **지난 시즌 빌라 유니폼**을 들고 있는 사진을 봤다」며, 「엔투라지가 여러 구단을 돌며 적합한 집인지 타진하는 형태로 보인다」고 해석했다. ⇒ 이적 협상 단계의 정황이고 결과적으로 영입은 성사됐다.\u000a⚠️ **후속 대조** — 같은 채널이 영입 후에 낸 스카우팅 영상(`HX_Ok0t7-e4`)에서는 음바예를 **「압박 몬스터·에메리 체인저」**로 강하게 긍정 평가했다. ⇒ **같은 채널 안에서 영입 전 회의론 → 영입 후 긍정으로 입장이 바뀌었다**는 사실 자체를 기록한다(서사 신뢰도 판단의 재료).\u000a⛔ **auto-caption 오인식** — 전사 전체에서 음바예가 **「Mbappé」**로 적혀 있다.'),NULL,'전사 헤더 파싱 + observations 역인용 산출 (scripts/index_transcripts.py, 2026-09-15)','MEDIUM-HIGH(메타) — 채널·제목·게시일은 전사 헤더 파싱값이다. ⚠️ 전사 본문은 **유튜브 자동 생성 자막**이라 오인식이 있다(docs/30 대조표) — 인용 시 auto-caption 명기·원문+번역 병기(불변규칙 11). 경기 귀속은 상대팀 표기+날짜 창으로 단일 특정된 건만 붙였다. · [요약 2026-09-15] summary/key_points는 **전사 원문을 읽고 쓴 것**이다(영상 미시청). ⚠️ auto-caption 오인식 가능 — 인물명·수치는 실측과 교차검증 필요(docs/30 대조표). 인용은 원문+한국어 번역 병기(불변규칙 11).');
